// ── Helpers ────────────────────────────────────────────────────────
function normaliseDomain(raw) {
  let d = raw.trim().toLowerCase();
  d = d.replace(/^[a-z][a-z0-9+.-]*:\/\//, '');
  d = d.split(/[/?#]/)[0].split(':')[0];
  if (d.startsWith('www.')) d = d.slice(4);
  return d.replace(/\.$/, '');
}

const LABEL_RE = /^(?!-)[a-z0-9-]{1,63}(?<!-)$/;
const TLD_RE   = /^[a-z]{2,63}$/;

function isValidDomain(domain) {
  if (!domain || domain.length > 253) return false;
  const labels = domain.split('.');
  if (labels.length < 2) return false;
  if (!labels.every(l => LABEL_RE.test(l))) return false;
  return TLD_RE.test(labels[labels.length - 1]);
}

function mapIndustry(text) {
  const key = (text || '').trim().toLowerCase();
  return key ? (INDUSTRY_MAP[key] || null) : null;
}

// ── DQ checks ──────────────────────────────────────────────────────
const items = $input.all();
const seenDomains = new Map();
const results = [];

for (let i = 0; i < items.length; i++) {
  const row = items[i].json;
  const rowNum = i + 1;
  const reasonCodes = [];
  const flags = [];
  let reasonDetails = [];

  const companyName = (row.company_name || '').trim();
  const rawDomain   = (row.domain || '').trim();

  // DQ-01: company_name and domain both present
  if (!companyName && !rawDomain) {
    reasonCodes.push('MISSING_REQUIRED');
    reasonDetails.push('both company_name and domain are blank');
  } else if (!companyName) {
    reasonCodes.push('MISSING_REQUIRED');
    reasonDetails.push('company_name is blank');
  } else if (!rawDomain) {
    reasonCodes.push('MISSING_REQUIRED');
    reasonDetails.push('domain is blank');
  }

  // DQ-02: valid domain after normalisation
  let normDomain = '';
  let domainValid = false;
  if (rawDomain) {
    normDomain = normaliseDomain(rawDomain);
    if (isValidDomain(normDomain)) {
      domainValid = true;
    } else {
      reasonCodes.push('INVALID_DOMAIN');
      reasonDetails.push(`domain "${normDomain}" is not a valid hostname`);
      normDomain = '';
    }
  }

  // DQ-05: employee_count numeric when present
  const rawEmp = (row.employee_count || '').toString().trim();
  let empNumeric = null;
  if (rawEmp) {
    const cleaned = rawEmp.replace(/,/g, '');
    if (/^\d+$/.test(cleaned) && parseInt(cleaned, 10) >= 0) {
      empNumeric = parseInt(cleaned, 10);
    } else {
      reasonCodes.push('HEADCOUNT_NOT_NUMERIC');
      reasonDetails.push(`employee_count "${rawEmp}" is not a whole number >= 0`);
    }
  }

  // DQ-06 / DQ-07: industry
  const rawIndustry = (row.industry || '').trim();
  let mappedIndustry = null;
  if (!rawIndustry) {
    flags.push('INDUSTRY_MISSING');
  } else {
    mappedIndustry = mapIndustry(rawIndustry);
    if (!mappedIndustry) {
      flags.push('INDUSTRY_UNMAPPED');
    }
  }

  // DQ-03: duplicate domain in batch (only on rows that passed DQ-02)
  if (domainValid) {
    if (seenDomains.has(normDomain)) {
      reasonCodes.push('DUPLICATE_IN_BATCH');
      reasonDetails.push(`domain "${normDomain}" first seen at row ${seenDomains.get(normDomain)}`);
    } else {
      seenDomains.set(normDomain, rowNum);
    }
  }

  const pass = reasonCodes.length === 0;

  results.push({
    json: {
      company_name: companyName,
      domain: rawDomain,
      industry: rawIndustry,
      employee_count: rawEmp,
      hq_city: (row.hq_city || '').trim(),
      hq_country: (row.hq_country || '').trim(),
      _row_number: rowNum,
      _normalised_domain: normDomain,
      _mapped_industry: mappedIndustry,
      _employee_count: empNumeric,
      _dq_pass: pass,
      _dq_reason_codes: reasonCodes.join('|'),
      _dq_flags: flags.join('|'),
      _dq_reason_detail: reasonDetails.join('; ')
    }
  });
}

return results;

// Prepare quarantine records for the data table
const items = $input.all();
const runId = $execution.id;
const now = new Date().toISOString();

return items.map(item => ({
  json: {
    run_id: runId,
    row_number: item.json._row_number,
    company_name: item.json.company_name,
    domain: item.json.domain,
    reason_codes: item.json._dq_reason_codes,
    reason_detail: item.json._dq_reason_detail,
    quarantined_at: now
  }
}));

// Build HubSpot batch-upsert payload from passing rows.
// Rows with INDUSTRY_MISSING or INDUSTRY_UNMAPPED flags load
// without industry (the field is omitted).
const items = $input.all();
const inputs = [];

for (const item of items) {
  const d = item.json;
  const props = {
    name: d.company_name,
    domain: d._normalised_domain,
    clay_domain_key: d._normalised_domain,
    city: d.hq_city,
    country: d.hq_country
  };
  // Only set industry if mapped
  if (d._mapped_industry) {
    props.industry = d._mapped_industry;
  }
  // Only set employee count if numeric
  if (d._employee_count !== null && d._employee_count !== undefined) {
    props.numberofemployees = d._employee_count;
  }
  inputs.push({
    idProperty: 'clay_domain_key',
    id: d._normalised_domain,
    properties: props
  });
}

// Return single item with the batch payload
return [{ json: { inputs } }];

// Parse the batch-upsert response and report create/update counts.
const items = $input.all();
const resp = items[0].json;
const results = resp.results || [];

let created = 0;
let updated = 0;
for (const r of results) {
  if (r.new === true) created++;
  else updated++;
}

return [{
  json: {
    status: resp.status,
    total: results.length,
    created,
    updated,
    results: results.map(r => ({
      id: r.id,
      name: r.properties?.name,
      domain: r.properties?.domain,
      action: r.new ? 'create' : 'update'
    }))
  }
}];
